import{_ as e,a as d,o,a4 as r}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse(`{"title":"Add-Product Search (Create-Order)","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-products-list","title":"Add-Product Search (Create-Order)","description":"The slim product search behind the admin Create-Order \\"Add Product\\" modal. NOT the product listing — for the full product list with all columns and filters use the List Products datagrid. Returns ALL statuses by default (admin must see disabled / draft products too). Booking products ARE listed here so admin can find them; they're blocked at admin cart add-to-cart time.","query":"curl -X GET \\"https://your-domain.com/api/admin/products?sku=SP-001&type=simple&per_page=30&page=1\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"sku=SP-001&type=simple&per_page=30&page=1\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 2512,\\n      \\"sku\\": \\"SP-001\\",\\n      \\"type\\": \\"simple\\",\\n      \\"name\\": \\"Arctic Cozy Knit Unisex Beanie\\",\\n      \\"status\\": 1,\\n      \\"price\\": 14,\\n      \\"formattedPrice\\": \\"$14.00\\",\\n      \\"baseImageUrl\\": \\"http://localhost:8000/cache/medium/product/2512/Muc0qeWks34MTZaxf38s6DBmfqMqrCxku81Uo8EB.webp\\",\\n      \\"isSaleable\\": true\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 30,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n","commonErrors":[{"error":"Unauthorized (401)","cause":"Missing or invalid admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/list.md","filePath":"api/rest-api/admin/catalog/products/list.md","lastUpdated":1783327468000}`),a={name:"api/rest-api/admin/catalog/products/list.md"};function c(i,t,n,s,l,p){return o(),d("div",null,t[0]||(t[0]=[r('<h1 id="add-product-search-create-order" tabindex="-1">Add-Product Search (Create-Order) <a class="header-anchor" href="#add-product-search-create-order" aria-label="Permalink to &quot;Add-Product Search (Create-Order)&quot;">​</a></h1><p>The slim product <strong>search</strong> that powers the admin <strong>Create Order</strong> screen&#39;s &quot;Add Product&quot; modal. It returns a compact row per product so an operator can quickly find and pick a product to add to a draft order.</p><div class="warning custom-block"><p class="custom-block-title">This is not the product listing</p><p>For the full admin product listing — every column plus all the Channel / Name / SKU / Attribute Family / Price / ID / Status / Type filters — use <a href="/api/rest-api/admin/catalog/products.html">List Products</a> (<code>GET /api/admin/catalog/products</code>). This page documents only the Create-Order search tool.</p></div><p>Results come back in the <code>{ data, meta }</code> envelope used by every admin collection.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/products</code></td><td>GET</td></tr></tbody></table><h2 id="how-it-differs-from-api-shop-products" tabindex="-1">How it differs from <code>/api/shop/products</code> <a class="header-anchor" href="#how-it-differs-from-api-shop-products" aria-label="Permalink to &quot;How it differs from `/api/shop/products`&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Shop</th><th>Admin</th></tr></thead><tbody><tr><td>Default status filter</td><td>Only <code>status = 1</code> and <code>visible_individually = 1</code></td><td><strong>No filter — all statuses returned</strong></td></tr><tr><td>Booking products</td><td>Hidden by shop visibility rules</td><td><strong>Listed</strong> (blocked only when added to admin draft cart)</td></tr><tr><td>Row payload</td><td>Full storefront fields (variants, prices, special prices, etc.)</td><td>Slim picker shape (9 fields)</td></tr><tr><td>Pagination response</td><td>Header-based (<code>X-Total-Count</code>, <code>X-Page</code>, ...)</td><td>Body envelope (<code>{ data, meta }</code>)</td></tr><tr><td>Authentication</td><td>Storefront key + optional customer Sanctum</td><td>Admin Sanctum token</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>Page number (default <code>1</code>)</td></tr><tr><td><code>per_page</code></td><td>integer</td><td>Items per page (default <code>30</code>, cap <code>50</code>)</td></tr><tr><td><code>query</code></td><td>string</td><td>Free-text — matches SKU OR product name (partial)</td></tr><tr><td><code>sku</code></td><td>string</td><td>Exact SKU</td></tr><tr><td><code>type</code></td><td>string</td><td><code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>downloadable</code>, <code>grouped</code>, <code>virtual</code>, <code>booking</code></td></tr><tr><td><code>status</code></td><td>integer</td><td><code>0</code> (disabled) or <code>1</code> (enabled) — omit to get both</td></tr><tr><td><code>categoryId</code></td><td>integer</td><td>Filter by category ID</td></tr><tr><td><code>channel</code></td><td>string</td><td>Channel code for value resolution</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code for value resolution</td></tr><tr><td><code>sort</code></td><td>string</td><td><code>id</code>, <code>sku</code>, <code>created_at</code>, <code>updated_at</code></td></tr><tr><td><code>order</code></td><td>string</td><td><code>asc</code> or <code>desc</code> (default <code>desc</code>)</td></tr></tbody></table><h2 id="row-shape" tabindex="-1">Row Shape <a class="header-anchor" href="#row-shape" aria-label="Permalink to &quot;Row Shape&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Product ID</td></tr><tr><td><code>sku</code></td><td>string</td><td>SKU</td></tr><tr><td><code>type</code></td><td>string</td><td>Product type</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Resolved via locale/channel if provided</td></tr><tr><td><code>status</code></td><td>integer|null</td><td><code>1</code> enabled / <code>0</code> disabled</td></tr><tr><td><code>price</code></td><td>number|null</td><td>Minimal price for the resolved customer group</td></tr><tr><td><code>formattedPrice</code></td><td>string|null</td><td>Locale-formatted price</td></tr><tr><td><code>baseImageUrl</code></td><td>string|null</td><td>Medium-cache image URL, falls back to original</td></tr><tr><td><code>isSaleable</code></td><td>boolean</td><td>Type-instance saleability check</td></tr></tbody></table><h2 id="booking-products" tabindex="-1">Booking Products <a class="header-anchor" href="#booking-products" aria-label="Permalink to &quot;Booking Products&quot;">​</a></h2><p>Booking products <strong>are returned</strong> by this endpoint so admin can find and review them. They are <strong>blocked</strong> at admin draft-cart add-to-cart time (<code>POST /api/admin/carts/{id}/items</code>) with HTTP <code>400</code> and the message &quot;Booking products cannot be added to an admin draft order.&quot; This matches the Bagisto monolith — the admin Create-Order UI does not ship a booking partial either.</p>',14)]))}const m=e(a,[["render",c]]);export{h as __pageData,m as default};
